import { notFound } from "next/navigation";

import type { AdminRecipe, ListRow, Neighbors, ProgressRow, ReviewState, SourceKey } from "@/lib/adminReviewShared";
import { createClient } from "@/lib/supabase/server";

export * from "@/lib/adminReviewShared";

/*
 * Admin review queue (M1.5.6). Every function here calls a SECURITY DEFINER
 * `admin_*` RPC that re-checks is_admin() inside Postgres; the TypeScript
 * checks are only there to answer 404 instead of leaking a 500.
 *
 * `src/types/database.ts` is regenerated by the integrator, so these RPCs are
 * reached through a deliberately loose call signature and typed here.
 */

type Rpc = {
  rpc(fn: string, args?: object): PromiseLike<{ data: unknown; error: { message: string; code?: string } | null }>;
};

async function call<T>(fn: string, args?: object): Promise<T> {
  const supabase = (await createClient()) as unknown as Rpc;
  const { data, error } = await supabase.rpc(fn, args);
  if (error) {
    // 42501 = the database said "not an admin". Anything else is a real fault.
    if (error.code === "42501") notFound();
    throw new Error(`${fn}: ${error.message}`);
  }
  return data as T;
}

/**
 * Gate for every /admin page: signed in AND in `admins`, else 404 (the route
 * does not admit it exists). The auth call verifies the token with the Auth
 * server; is_admin() is the database's own answer.
 */
export async function requireAdmin(): Promise<{ userId: string }> {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) notFound();
  const { data, error } = await (supabase as unknown as Rpc).rpc("is_admin");
  if (error || data !== true) notFound();
  return { userId: user.id };
}

export const getProgress = () => call<ProgressRow[]>("admin_review_progress");

export const getRecipeDetail = (slug: string) => call<AdminRecipe | null>("admin_recipe_detail", { p_slug: slug });

export async function getNeighbors(slug: string, state: ReviewState, source: SourceKey | null): Promise<Neighbors> {
  const rows = await call<Neighbors[]>("admin_review_neighbors", {
    p_slug: slug,
    p_state: state,
    p_source: source,
  });
  return rows[0] ?? { prev_slug: null, next_slug: null, total: 0 };
}

export const getReviewList = (state: ReviewState, source: SourceKey | null, after: string | null, limit = 50) =>
  call<ListRow[]>("admin_review_list", { p_state: state, p_source: source, p_after: after, p_limit: limit });

/** First slug in a filter, for when the URL names no recipe. */
export async function getFirstSlug(state: ReviewState, source: SourceKey | null): Promise<string | null> {
  const rows = await getReviewList(state, source, null, 1);
  return rows[0]?.slug ?? null;
}

